class BalanceGroup extends HttpApiGroup.make("balance")
  .add(HttpApiEndpoint.get("readBalance", "/shoppers/:shopper_id/balance", { params: BalanceReadBalancePathParams, query: BalanceReadBalanceQuery, success: BalanceReadBalance200, error: [BalanceReadBalance400.pipe(HttpApiSchema.status(400)), BalanceReadBalance401.pipe(HttpApiSchema.status(401)), BalanceReadBalance404.pipe(HttpApiSchema.status(404)), BalanceReadBalance500] })
      .annotate(OpenApi.Identifier, "balance.readBalance"), 
    HttpApiEndpoint.post("topUp", "/shoppers/:shopper_id/top-ups", { params: BalanceTopUpPathParams, payload: BalanceTopUpRequestJson, success: BalanceTopUp202.pipe(HttpApiSchema.status(202)), error: [BalanceTopUp400.pipe(HttpApiSchema.status(400)), BalanceTopUp404.pipe(HttpApiSchema.status(404)), BalanceTopUp409.pipe(HttpApiSchema.status(409)), BalanceTopUp500] })
      .annotate(OpenApi.Identifier, "balance.topUp")) {}

class OrdersGroup extends HttpApiGroup.make("orders")
  .add(HttpApiEndpoint.post("place", "/shoppers/:shopper_id/orders", { params: OrdersPlacePathParams, query: OrdersPlaceQuery, payload: OrdersPlaceRequestJson, success: OrdersPlace201.pipe(HttpApiSchema.status(201)), error: [OrdersPlace400.pipe(HttpApiSchema.status(400)), OrdersPlace500] })
      .annotate(OpenApi.Identifier, "orders.place")) {}

export class ShopApi extends HttpApi.make("ShopApi")
  .annotate(OpenApi.Title, "ShopApi")
  .annotate(OpenApi.Version, "1.0.0")
  .add(BalanceGroup, OrdersGroup) {}

